<?php
declare(strict_types=1);
date_default_timezone_set('Asia/Tehran');
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
const D=__DIR__.'/_data';
require_once __DIR__.'/platform-v3.php';
function bw_copy_tree(string $src,string $dst):void{if(!is_dir($src))return;if(!is_dir($dst))mkdir($dst,0750,true);foreach(scandir($src)?:[] as $n){if($n==='.'||$n==='..')continue;$a=$src.'/'.$n;$b=$dst.'/'.$n;if(is_dir($a))bw_copy_tree($a,$b);elseif(is_file($a)){copy($a,$b);@chmod($b,0640);}}}
function bw_rm(string $p):void{if(!is_dir($p))return;foreach(scandir($p)?:[] as $n){if($n==='.'||$n==='..')continue;$x=$p.'/'.$n;if(is_dir($x))bw_rm($x);else @unlink($x);}@rmdir($p);}
$statusFile=D.'/_backup_status.json';$force=in_array('--force',$argv??[],true);$old=ws_raw_read($statusFile);$last=strtotime((string)($old['completed_at']??''))?:0;if(!$force&&$last>time()-72000){echo "BACKUP_NOT_DUE\n";exit(0);} 
$home=dirname(__DIR__,2);$base=$home.'/websaza_backups';if(!is_dir($base)&&!mkdir($base,0700,true)){ws_raw_write($statusFile,['ok'=>false,'error'=>'mkdir_failed','checked_at'=>ws_now()]);exit(1);} 
$name=date('Ymd_His');$dir=$base.'/'.$name;if(!mkdir($dir,0700,true)){ws_raw_write($statusFile,['ok'=>false,'error'=>'snapshot_mkdir_failed','checked_at'=>ws_now()]);exit(1);} 
try{$db=ws_db();if(!$db)throw new RuntimeException('sqlite_unavailable');$db->exec('PRAGMA wal_checkpoint(FULL)');$target=$dir.'/websaza.sqlite3';$quoted=str_replace("'","''",$target);$db->exec("VACUUM INTO '".$quoted."'");@chmod($target,0600);foreach(['settings.json','admin.json','_login_security.json','_login_secret','_admin_trusted_devices.json','contact_registry.json'] as $n){$src=D.'/'.$n;if(is_file($src)){copy($src,$dir.'/'.$n);@chmod($dir.'/'.$n,0600);}}bw_copy_tree(D.'/receipts',$dir.'/receipts');$files=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS));foreach($it as $f)if($f->isFile()){$rel=substr($f->getPathname(),strlen($dir)+1);$files[$rel]=hash_file('sha256',$f->getPathname());}$manifest=['version'=>'backup-v1','created_at'=>ws_now(),'release'=>'platform-v4','files'=>$files];file_put_contents($dir.'/manifest.json',json_encode($manifest,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);@chmod($dir.'/manifest.json',0600);
$dirs=[];foreach(scandir($base)?:[] as $n)if(preg_match('/^\d{8}_\d{6}$/',$n)&&is_dir($base.'/'.$n))$dirs[]=$n;rsort($dirs);$keep=[];$weeks=[];$months=[];foreach($dirs as $i=>$n){$ts=DateTimeImmutable::createFromFormat('Ymd_His',$n,new DateTimeZone('Asia/Tehran'));if(!$ts)continue;if($i<14){$keep[$n]=1;continue;}$w=$ts->format('o-W');$m=$ts->format('Y-m');if(count($weeks)<12&&!isset($weeks[$w])){$weeks[$w]=1;$keep[$n]=1;continue;}if(count($months)<12&&!isset($months[$m])){$months[$m]=1;$keep[$n]=1;}}
foreach($dirs as $n)if(!isset($keep[$n]))bw_rm($base.'/'.$n);$status=['ok'=>true,'completed_at'=>ws_now(),'snapshot'=>$name,'files'=>count($files),'retained'=>count($keep)];ws_raw_write($statusFile,$status);echo "BACKUP_OK {$name}\n";}catch(Throwable $e){bw_rm($dir);ws_raw_write($statusFile,['ok'=>false,'error'=>'backup_failed','checked_at'=>ws_now()]);fwrite(STDERR,"BACKUP_FAILED\n");exit(1);} 
